from lib import *
chapter(7,'maths','a-peek-beyond-the-point','A Peek Beyond the Point',
 ('A pencil and a ruler','A pencil is 14.5 cm long. A bead is 0.8 cm wide. Between whole numbers there are parts. Decimals describe those parts, and this chapter looks beyond the decimal point.'),
 [('Decimals and place value',['A decimal point separates the whole part from the fractional part.','The first place after the point is tenths, then hundredths, then thousandths.','In 3.47, the 4 means 4 tenths and the 7 means 7 hundredths.']),
  ('Comparing decimals',['Compare the whole parts first. If they are equal, compare the tenths, then hundredths.','0.8 is greater than 0.75 because 0.80 is greater than 0.75. Zeros at the end of the decimal part do not change its value.']),
  ('Rounding and units',['To round to one decimal place, look at the hundredths digit. If it is 5 or more, round up.','1 cm is 10 mm, so 1 mm is 0.1 cm. 1 m is 100 cm, so 1 cm is 0.01 m.'])],
 [('Compare 0.8 and 0.75.',[('Write 0.8 as 0.80.','Same number of places.'),('80 hundredths is more than 75 hundredths, so 0.8 is greater.','Compare.')]),
  ('Round 3.47 to one decimal place.',[('Hundredths digit is 7, which is 5 or more.','Look at the next place.'),('Round up the 4 to 5: 3.5.','Result.')])],
 ('Why is 0.5 the same as 0.50 but 5 is not the same as 0.5?',['Zeros after the last decimal digit do not change value.','Position of the point matters.'],['Thinking longer decimals are larger.','Putting the point in the wrong place.']),
 ['Decimal places: tenths, hundredths, thousandths.','Compare whole parts, then tenths, then hundredths.','Zeros at the end of a decimal can be added or dropped.','Round by looking at the next digit.'],
 [mcq('d3-1',1,'In 3.47 the digit 4 is in the','tenths place',[('hundredths place','That is the digit 7.'),('ones place','That is 3.')],'First place after the point.'),
  mcq('d3-2',1,'Which is greater?','0.8',[('0.75','0.8 equals 0.80.'),('0.07','Much smaller.')],'80 hundredths beats 75 hundredths.'),
  num('d3-3',1,'Round 3.47 to one decimal place.',3.5,'The hundredths digit 7 rounds the 4 up.',[(3.4,'You rounded down.')]),
  tf('d3-4',1,'0.5 and 0.50 are equal.',True,'Trailing zeros add no value.'),
  num('d3-5',2,'How many mm in 0.8 cm?',8,'1 cm is 10 mm.',[(80,'0.8 times 10 is 8.')],'mm'),
  mcq('d3-6',2,'0.25 as a fraction is','25/100',[('2/5','That equals 0.4.'),('1/5','That is 0.2.')],'Hundredths.'),
  mcq('d3-7',2,'Which is smallest?','0.09',[('0.1','0.1 is 0.10.'),('0.9','Larger.')],'9 hundredths.'),
  num('d3-8',2,'Round 6.249 to the nearest tenth.',6.2,'The hundredths digit is 4, so round down.',[(6.3,'4 is less than 5.')]),
  mcq('d3-9',3,'3 + 4/10 + 7/100 =','3.47',[('3.74','Digits are in the wrong order.'),('34.7','The point is in the wrong place.')],'Place values.'),
  num('d3-10',3,'1 cm is how many metres?',0.01,'100 cm make 1 m.',[(0.1,'That is 10 cm.')],'m')],
 keep=['decimal','tenths','hundredths'])
chapter(7,'maths','expressions-using-letter-numbers','Expressions Using Letter-Numbers',
 ('The mystery pack','A packet has some biscuits, but we do not know how many. If Ravi has 3 packets plus 2 loose biscuits, how many does he have? We write 3n plus 2, where n is the number in a packet.'),
 [('Letter-numbers',['A letter standing for a number that can change is called a variable or letter-number.','Letters let us write general rules. The perimeter of a square with side s is 4s.','In 4s we write 4 times s without the multiplication sign.']),
  ('Forming expressions',['3 more than a number n is n plus 3. Twice a number n is 2n. 5 less than n is n minus 5.','An expression is made from letter-numbers, numbers and operations.']),
  ('Evaluating and simplifying',['To evaluate an expression, put a value in place of the letter and compute. If n is 4, then 3n plus 2 equals 14.','Like terms, which have the same letter, can be added. 3n plus 2n equals 5n.','Unlike terms cannot be combined: 3n plus 2 stays as it is.','Expressions model situations, such as the cost of n pens at Rs 5 each, which is 5n.'])],
 [('Find the value of 3n + 2 when n = 4.',[('Replace n by 4.','Substitute.'),('3 times 4 is 12; 12 plus 2 is 14.','Compute.')]),
  ('Simplify 4a + 3a - 2.',[('Combine like terms: 4a plus 3a is 7a.','Same letter.'),('The answer is 7a minus 2.','Cannot combine with 2.')])],
 ('Explain why 3n + 2 is not 5n.',['3n and 2 are unlike terms.','Only like terms combine.'],['Adding letters and numbers.','Writing 2n as 2 + n.']),
 ['A letter-number stands for a changing number.','4s means 4 times s.','Evaluate by substituting.','Only like terms can be added.'],
 [mcq('e4-1',1,'Twice a number n is written','2n',[('n + 2','That is 2 more than n.'),('n / 2','That is half of n.')],'Twice means times 2.'),
  mcq('e4-2',1,'The perimeter of a square with side s is','4s',[('s + 4','Add the four sides.'),('s squared','That is the area.')],'Four equal sides.'),
  num('e4-3',1,'Value of 3n + 2 when n = 4',14,'3 times 4 plus 2.',[(9,'Do not add 3 + 4 + 2.')]),
  tf('e4-4',1,'3n + 2 equals 5n.',False,'3n and 2 are unlike terms.'),
  mcq('e4-5',2,'Simplify 5a + 2a','7a',[('10a','2 and 5 add to 7.'),('7','The letter stays.')],'Like terms.'),
  num('e4-6',2,'Cost in Rs of n pens at Rs 5 each when n = 6',30,'5 times 6.',[(11,'That adds 5 and 6.')]),
  mcq('e4-7',2,'5 less than n is','n - 5',[('5 - n','That is n less than 5.'),('5n','That is 5 times n.')],'Subtract 5.'),
  mcq('e4-8',2,'Which are like terms?','3x and 7x',[('3x and 7y','Different letters.'),('3x and 7','One has no letter.')],'The same letter.'),
  num('e4-9',3,'If a = 3, what is 2a + a?',9,'2a plus a is 3a: 3 times 3.',[(6,'You forgot the second a.')]),
  mcq('e4-10',3,'The sum of x and 3 times y is','x + 3y',[('3xy','This is a product.'),('3x + y','The 3 belongs to y.')],'Add x to 3y.')],
 keep=['variable','expression','like terms'])
